import React from 'react';
import { Helmet } from 'react-helmet';
import Header from './header';
import Footer from './Footer';
import Credentials from './Credentials';
import ContentSidebar from './ContentSidebar';
import '../Styles/ContentPage.css';
import { CONTENT_PAGES, type ContentPageData } from '../data/contentPages';
import {
  BUSINESS,
  SERVICE_CITIES,
  SITE_URL,
  ZIP_PAGES,
  breadcrumbSchema,
  faqSchema,
  localBusinessSchema,
} from '../data/business';
import { REVIEWS, reviewByline } from '../data/reviews';

const SECTION_LABELS = {
  city: { name: 'Service Areas', path: '/service-areas/' },
  service: { name: 'Services', path: '/#services' },
  guide: { name: 'Roofing Guides', path: '/roofing-guides/' },
  zip: { name: 'Service Areas', path: '/service-areas/' },
};

const articleSchema = (page: ContentPageData) => ({
  '@context': 'https://schema.org',
  '@type': 'Article',
  headline: page.h1,
  description: page.metaDescription,
  image: `${SITE_URL}${page.image}`,
  datePublished: page.updated,
  dateModified: page.updated,
  mainEntityOfPage: `${SITE_URL}${page.slug}`,
  author: { '@type': 'Organization', name: BUSINESS.name, url: `${SITE_URL}/` },
  publisher: { '@id': `${SITE_URL}/#business` },
});

// Names the exact area a page covers, down to the ZIP code on ZIP pages.
const serviceSchema = (page: ContentPageData) => ({
  '@context': 'https://schema.org',
  '@type': 'Service',
  name: page.h1,
  serviceType: 'Roofing contractor',
  description: page.metaDescription,
  url: `${SITE_URL}${page.slug}`,
  provider: { '@id': `${SITE_URL}/#business` },
  areaServed: page.zip
    ? {
        '@type': 'Place',
        name: `${page.city}, ID ${page.zip}`,
        address: {
          '@type': 'PostalAddress',
          postalCode: page.zip,
          addressLocality: page.city,
          addressRegion: 'ID',
          addressCountry: 'US',
        },
      }
    : page.city
      ? { '@type': 'City', name: `${page.city}, ID` }
      : { '@type': 'AdministrativeArea', name: 'Treasure Valley, Idaho' },
});

const ContentPage: React.FC<{ slug: string }> = ({ slug }) => {
  const page = CONTENT_PAGES[slug];
  const cityPage = SERVICE_CITIES.find((city) => city.name === page.city && city.path !== page.slug);
  const crumbs = [
    { name: 'Home', path: '/' },
    SECTION_LABELS[page.kind],
    ...(page.kind === 'zip' && cityPage ? [{ name: page.city as string, path: cityPage.path }] : []),
    { name: page.h1, path: page.slug },
  ];
  const zipPages = ZIP_PAGES.filter((zipPage) => zipPage.city === page.city && zipPage.path !== page.slug);
  const previewImage = page.ogImage ?? page.image;

  return (
    <>
      <Helmet>
        <title>{page.metaTitle}</title>
        <meta name="description" content={page.metaDescription} />
        <meta property="og:title" content={page.metaTitle} />
        <meta property="og:description" content={page.metaDescription} />
        <meta property="og:image" content={`${SITE_URL}${previewImage}`} />
        <meta property="og:url" content={`${SITE_URL}${page.slug}`} />
        <meta property="og:type" content={page.kind === 'guide' ? 'article' : 'website'} />
        <meta name="twitter:card" content="summary_large_image" />
        <script type="application/ld+json">{JSON.stringify(localBusinessSchema(page.slug))}</script>
        <script type="application/ld+json">{JSON.stringify(breadcrumbSchema(crumbs))}</script>
        {page.faqs && <script type="application/ld+json">{JSON.stringify(faqSchema(page.faqs))}</script>}
        {page.kind === 'guide' && <script type="application/ld+json">{JSON.stringify(articleSchema(page))}</script>}
        {page.kind !== 'guide' && <script type="application/ld+json">{JSON.stringify(serviceSchema(page))}</script>}
      </Helmet>

      <Header />

      <main className="cp-page">
        <section className="cp-hero">
          <div className="cp-hero-inner">
            <nav className="cp-breadcrumbs" aria-label="Breadcrumb">
              {crumbs.slice(0, -1).map((crumb) => (
                <span key={crumb.path}>
                  <a href={crumb.path}>{crumb.name}</a> /{' '}
                </span>
              ))}
              <span aria-current="page">{page.h1}</span>
            </nav>
            <h1>{page.h1}</h1>
            <p className="cp-lede">{page.lede}</p>
            <div className="cp-actions">
              <a href={BUSINESS.phoneHref} className="cp-btn cp-btn--primary">Call {BUSINESS.phoneDisplay}</a>
              <a href="/contact/" className="cp-btn cp-btn--ghost">Request a Free Estimate</a>
            </div>
          </div>
        </section>

        <div className="cp-layout">
          <article className="cp-article">
          <figure className="cp-figure">
            <img src={page.image} alt={page.imageAlt} loading="eager" />
            {page.imageCaption && <figcaption className="cp-caption">{page.imageCaption}</figcaption>}
          </figure>

          {page.kind === 'guide' && (
            <p className="cp-meta">By {BUSINESS.name} • Updated {page.updatedLabel}</p>
          )}

          {page.sections.map((section) => (
            <section key={section.heading} className="cp-section">
              <h2>{section.heading}</h2>
              {section.paragraphs?.map((paragraph) => (
                <p key={paragraph}>{paragraph}</p>
              ))}
              {section.bullets && (
                <ul>
                  {section.bullets.map((bullet) => (
                    <li key={bullet}>{bullet}</li>
                  ))}
                </ul>
              )}
              {section.closing && <p>{section.closing}</p>}
            </section>
          ))}

          {page.reviews && (
            <section className="cp-section">
              <h2>What homeowners say</h2>
              {page.reviews.map((key) => (
                <blockquote key={key} className="cp-quote">
                  “{REVIEWS[key].text}”
                  <cite>— {reviewByline(REVIEWS[key])}</cite>
                </blockquote>
              ))}
            </section>
          )}

          {page.faqs && (
            <section className="cp-section">
              <h2>Frequently asked questions</h2>
              {page.faqs.map((faq) => (
                <div key={faq.question} className="cp-faq">
                  <h3>{faq.question}</h3>
                  <p>{faq.answer}</p>
                </div>
              ))}
            </section>
          )}

          {zipPages.length > 0 && (
            <section className="cp-section">
              <h2>{page.kind === 'zip' ? `Other ${page.city} ZIP codes we serve` : `${page.city} ZIP codes we serve`}</h2>
              <ul className="cp-link-list cp-link-list--compact">
                {zipPages.map((zipPage) => (
                  <li key={zipPage.path}>
                    <a href={zipPage.path}>{zipPage.city} {zipPage.zip}</a>
                  </li>
                ))}
              </ul>
            </section>
          )}

          <aside className="cp-cta">
            <h2>{page.ctaHeading}</h2>
            <p>
              Call {BUSINESS.phoneDisplay} or send us a message and we'll help you understand your options. Prefer a quick
              number first? Try our instant quote tool.
            </p>
            <div className="cp-actions">
              <a href={BUSINESS.phoneHref} className="cp-btn cp-btn--primary">Call {BUSINESS.phoneDisplay}</a>
              <a href="/contact/" className="cp-btn cp-btn--ghost">Contact Us</a>
              <a href="/instant-quote/" className="cp-btn cp-btn--ghost">Instant Quote</a>
            </div>
          </aside>

          <section className="cp-section">
            <h2>Related pages</h2>
            <ul className="cp-link-list">
              {page.related.map((relatedSlug) => (
                <li key={relatedSlug}>
                  <a href={relatedSlug}>{CONTENT_PAGES[relatedSlug].h1}</a>
                </li>
              ))}
            </ul>
          </section>
          </article>

          <ContentSidebar />
        </div>

        <Credentials />
      </main>

      <Footer />
    </>
  );
};

export default ContentPage;
